    bodyHtml: `<h3 class="holo-text" style="margin-bottom:12px">OSPF — Open Shortest Path First</h3>
<p style="color:var(--text-secondary);margin-bottom:16px">OSPF is a link-state routing protocol that uses the Dijkstra algorithm to calculate the shortest path tree. It's the most widely used IGP in enterprise networks.</p>

<h4 style="margin:12px 0 8px;">OSPF Neighbor States</h4>
<div class="neu-inset" style="padding:14px;font-size:13px;line-height:1.8;">
<strong style="color:#ef4444;">Down</strong> → <strong style="color:#f59e0b;">Init</strong> → <strong style="color:#eab308;">2-Way</strong> → <strong style="color:#3b82f6;">ExStart</strong> → <strong style="color:#8b5cf6;">Exchange</strong> → <strong style="color:#06b6d4;">Loading</strong> → <strong style="color:#10b981;">Full</strong>
</div>

<h4 style="margin:16px 0 8px;">OSPF Requirements for Neighbors</h4>
<ul style="font-size:13px;color:var(--text-secondary);line-height:1.8;padding-left:20px;">
<li>Same Area ID</li><li>Same Hello/Dead timers (default: 10/40 on broadcast)</li>
<li>Same subnet and mask</li><li>Same authentication</li><li>Same MTU (for DBD exchange)</li>
<li>Same network type</li><li>Not a passive interface</li>
</ul>

<h4 style="margin:16px 0 8px;">OSPF Area Types</h4>
<table style="width:100%;border-collapse:collapse;font-size:13px;">
<tbody><tr style="background:rgba(99,102,241,0.1);"><th style="padding:6px;border-bottom:1px solid var(--glass-border);">Area Type</th><th style="padding:6px;border-bottom:1px solid var(--glass-border);">LSA Types Allowed</th><th style="padding:6px;border-bottom:1px solid var(--glass-border);">External Routes?</th></tr>
<tr><td style="padding:6px;border-bottom:1px solid var(--glass-border);">Normal</td><td style="padding:6px;border-bottom:1px solid var(--glass-border);">1, 2, 3, 4, 5</td><td style="padding:6px;border-bottom:1px solid var(--glass-border);">Yes</td></tr>
<tr><td style="padding:6px;border-bottom:1px solid var(--glass-border);">Stub</td><td style="padding:6px;border-bottom:1px solid var(--glass-border);">1, 2, 3</td><td style="padding:6px;border-bottom:1px solid var(--glass-border);">No (default route instead)</td></tr>
<tr><td style="padding:6px;border-bottom:1px solid var(--glass-border);">Totally Stubby</td><td style="padding:6px;border-bottom:1px solid var(--glass-border);">1, 2</td><td style="padding:6px;border-bottom:1px solid var(--glass-border);">No (only default route)</td></tr>
<tr><td style="padding:6px;border-bottom:1px solid var(--glass-border);">NSSA</td><td style="padding:6px;border-bottom:1px solid var(--glass-border);">1, 2, 3, 7</td><td style="padding:6px;border-bottom:1px solid var(--glass-border);">LSA 7 → converted to 5 at ABR</td></tr>
</tbody></table>`,
